// ExtractorFS is test-only (E01-04.early_faults). When it is not nil, New opens
// the store on this file system instead of the OS file system, so a fault
// probe can drop the unsynced data of a power loss. Production leaves it nil.
var ExtractorFS vfs.FS

const (
	// minCache is the minimum amount of memory in megabytes to allocate to pebble

if ExtractorFS != nil {
	opt.FS = ExtractorFS
}
innerDB, err := pebble.Open(file, opt)

// ExtractorWrap is test-only (E01-04.early_faults). When it is not nil, the
// node's pebble key-value store is passed through it, so a fault probe can
// wrap the store the node and the extractor packages use. Production leaves
// it nil.
var ExtractorWrap func(ethdb.KeyValueStore) ethdb.KeyValueStore

func newPebbleDBDatabase(file string, cache int, handles int, namespace string, readonly bool) (ethdb.KeyValueStore, error) {

patches.original:
	db, err := pebble.New(file, cache, handles, namespace, readonly)
	if err != nil {
		return nil, err
	}
	return db, nil
}

patches.replacement:
	db, err := pebble.New(file, cache, handles, namespace, readonly)
	if err != nil {
		return nil, err
	}
	if ExtractorWrap != nil {
		return ExtractorWrap(db), nil
	}
	return db, nil
}
